							let sx = zone.x;
							let sz = zone.z;
							if (stepsPos === "west") sx = zone.x - zone.width / 2 + .16 + stepTread / 2 + s * stepTread;
							else if (stepsPos === "east") sx = zone.x + zone.width / 2 - .16 - stepTread / 2 - s * stepTread;
							else if (stepsPos === "north") sz = zone.z - zone.depth / 2 + .16 + stepTread / 2 + s * stepTread;
							else if (stepsPos === "south") sz = zone.z + zone.depth / 2 - .16 - stepTread / 2 - s * stepTread;
