									const s1 = (q1[0] - p1[0]) * ux + (q1[1] - p1[1]) * uz;
									const s2 = (q2[0] - p1[0]) * ux + (q2[1] - p1[1]) * uz;
									const ovMin = Math.max(-.14 / 2, Math.min(s1, s2));
									const ovMax = Math.min(edgeLen + wallT / 2, Math.max(s1, s2));
